import 'package:flutter/material.dart';
import '../../services/settings_service.dart';
class SettingsScreen extends StatefulWidget { const SettingsScreen({super.key}); @override State<SettingsScreen> createState() => _SettingsScreenState(); }
class _SettingsScreenState extends State<SettingsScreen> { final settings = GameSettings.instance; @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Settings')), body: ListView(padding: const EdgeInsets.all(16), children: [Card(child: Column(children: [SwitchListTile(title: const Text('Sound effects'), value: settings.soundEnabled, onChanged: (v) => setState(() => settings.soundEnabled = v)), SwitchListTile(title: const Text('Vibration'), value: settings.vibrationEnabled, onChanged: (v) => setState(() => settings.vibrationEnabled = v)), SwitchListTile(title: const Text('Animations'), value: settings.animationsEnabled, onChanged: (v) => setState(() => settings.animationsEnabled = v)), SwitchListTile(title: const Text('Dark theme'), value: settings.darkTheme, onChanged: (v) { settings.darkTheme = v; setState(() {}); })])), Card(child: ListTile(title: const Text('Language'), subtitle: const Text('العربية • Français • English'), trailing: const Icon(Icons.language))) ])); }
}
